css:
.center {
  display: flex;
  justify-content: center;
  align-items: center;
}
.design {
  height: 200px;
  width: 200px;
  border-radius: 40px;
  background: rgb(255, 11, 0);
  background: linear-gradient(
    180deg,
    rgba(255, 11, 0, 1) 13%,
    rgba(255, 158, 0, 1) 100%
  );
  position: relative;
  overflow: hidden;
  transition: 1s ease-in-out;
}

.design:hover {
  background: linear-gradient(180deg, #00000e 13%, #353283 100%);
}

.color-border {
  border-radius: 50%;
  background-color: #ffffff20;
  box-shadow: 0px 0px 10px 2px rgba(0, 0, 0, 0.1);
  animation: sun 3s infinite;
}
.circle-1 {
  height: 220px;
  width: 220px;
  position: absolute;
  right: -50px;
  top: -50px;
}
.circle-2 {
  height: 180px;
  width: 180px;
}
.circle-3 {
  height: 140px;
  width: 140px;
}
.circle-4 {
  height: 105px;
  width: 105px;
}
.circle-5 {
  height: 70px;
  width: 70px;
  border-radius: 50%;
  background-color: #ffffff;
}

.shape {
  height: 200px;
  width: 200px;
  background-color: #484848;
  transform: rotate(45deg);
  position: absolute;
}
.shadow {
  box-shadow: 0px 0px 20px 0px rgba(0, 0, 0, 0.75);
}
.mountain-1 {
  z-index: 1;
  bottom: -100px;
  left: -100px;
  animation: motion 5s infinite;
}
.mountain-2 {
  bottom: -110px;
  left: -30px;
  animation: motion1 5s infinite;
  animation-delay: 1s;
}
.mountain-3 {
  z-index: 2;
  bottom: -150px;
  left: 90px;
  animation: motion2 5s infinite;
  animation-delay: 0.5s;
}

@keyframes motion {
  40% {
    bottom: -95px;
    left: -95px;
  }
  80% {
    bottom: -98px;
    left: -98px;
  }
}

@keyframes motion1 {
  30% {
    left: -25px;
  }
  80% {
    left: -28px;
  }
}

@keyframes motion2 {
  40% {
    bottom: -145px;
    left: 85px;
  }
  80% {
    bottom: -148px;
    left: 88px;
  }
}

@keyframes sun {
  80% {
    right: -48px;
    top: -48px;
  }
}
